///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name digitalChangePage
 * @description digital Change Page 처리
 * @param {*} tab tab
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.digitalChangePage = async function (tab) {
    scwin.form = (document.digitalListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_DigitalChangePageReq').get('lastSaveStatCd'));
    if (lastSaveStatCdInt === 0 && tab > 1) {
        await $c.win.alert('발행증권에 관한 사항을 먼저 저장해주세요.');
        return;
    } else {
        if (lastSaveStatCdInt === 1 && tab > 2) {
            await $c.win.alert('상장신청인에 관한 사항을 먼저 저장해주세요.');
            return;
        } else {
            if (lastSaveStatCdInt === 2 && tab > 3) {
                await $c.win.alert('기타사항을 먼저 저장해주세요.');
                return;
            }
        }
    }
    if (tab === 1) {
        return;
    } else {
        if (tab === 2) {
            $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewIsurTab');
        } else {
            if (tab === 3) {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewSrtyLpTab');
            } else {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewAttachFileTab');
            }
        }
    }
    scwin.form.action = 'DigitalList.do';
    await scwin.tx_fn_DigitalChangePage();
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (!await $c.fil.confirmJob('I')) {
        return;
    }
    scwin.removeComma(1);
    if (!await scwin.mmCheck()) {
        scwin.insertComma(1);
        return;
    }
    if (!fn_validate(1)) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_validate — 폼·DOM 의존(B-7)
        scwin.insertComma(1);
        return;
    }
    if (!await scwin.valid()) {
        scwin.insertComma(1);
        return;
    }
    $('input[name=rd_secugrpId]').prop('disabled', '');
    $c.util.getComponent("ipt_designComNm").setDisabled(false);
    $c.util.getComponent("ipt_comNm").setDisabled(false);
    (($c.util.getComponent('ipt_isurCd')) && ($c.util.getComponent('ipt_isurCd')).setDisabled ? ($c.util.getComponent('ipt_isurCd')).setDisabled((('') === '' || ('') === false || ('') === 'false') ? false : ((('') === true || ('') === 'true' || ('') === 'disabled') ? true : (''))) : void 0);
    (($c.util.getComponent('ipt_designAdvserIsurCd')) && ($c.util.getComponent('ipt_designAdvserIsurCd')).setDisabled ? ($c.util.getComponent('ipt_designAdvserIsurCd')).setDisabled((('') === '' || ('') === false || ('') === 'false') ? false : ((('') === true || ('') === 'true' || ('') === 'disabled') ? true : (''))) : void 0);
    $c.util.getComponent("ipt_trstCustdnNm").setDisabled(false);
    (($c.util.getComponent('ipt_trstInstIsurCd')) && ($c.util.getComponent('ipt_trstInstIsurCd')).setDisabled ? ($c.util.getComponent('ipt_trstInstIsurCd')).setDisabled((('') === '' || ('') === false || ('') === 'false') ? false : ((('') === true || ('') === 'true' || ('') === 'disabled') ? true : (''))) : void 0);
    $c.util.getComponent("ipt_trstInstIsurNm").setDisabled(false);
    $c.util.getComponent("ipt_digitalSecuUlyNm").setDisabled(false);
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = 'DigitalList.do';
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'saveIsuTab');
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name valid
 * @description valid 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.valid = async function () {
    if ($c.util.getComponent("ipt_isuNm").getValue() === '' || $c.util.getComponent("ipt_isuNm").getValue() == null) {
        await $c.win.alert("한글종목명은 필수입니다.");
        return false;
    }
    if ($("input[type=radio][name='pubofrYn']:checked").val() === '' || $("input[type=radio][name='pubofrYn']:checked").val() == null) {
        await $c.win.alert("추가발행 여부를 선택해주세요.");
        return false;
    }
    if ($c.util.getComponent("ipt_isuAbbrv").getValue() === '' || $c.util.getComponent("ipt_isuAbbrv").getValue() == null) {
        await $c.win.alert("한글종목약명은 필수입니다.");
        return false;
    }
    if ($c.util.getComponent("ipt_isuEngNm").getValue() === '' || $c.util.getComponent("ipt_isuEngNm").getValue() == null) {
        await $c.win.alert("영문종목명은 필수입니다.");
        return false;
    }
    if ($c.util.getComponent("ipt_isuEngAbbrv").getValue() === '' || $c.util.getComponent("ipt_isuEngAbbrv").getValue() == null) {
        await $c.win.alert("영문종목약명은 필수입니다.");
        return false;
    }
    if ($c.util.getComponent("ipt_addListRnd").getValue() === '' || $c.util.getComponent("ipt_addListRnd").getValue() == null) {
        await $c.win.alert("추가상장회차는 필수입니다.");
        return false;
    }
    if ($c.util.getComponent("ipt_listQty").getValue() === '' || $c.util.getComponent("ipt_listQty").getValue() == null) {
