            mm = mmdd.substring(0, 2);
            dd = mmdd.substring(2, 4);
            $("select[name='distrPayBasM" + i + "']").val(mm).prop("selected", true);
            $("select[name='distrPayBasD" + i + "']").val(dd).prop("selected", true);
        }
    }
};

